static boolean isLikelyLivelock(Thread t, long observeMs) throws InterruptedException {
    long koniec = System.currentTimeMillis() + observeMs;
    while (System.currentTimeMillis() < koniec) {
        if (t.getState() != Thread.State.RUNNABLE) return false;
        Thread.sleep(50);
    }
    return true;
}
