static <T> T retryWithBackoffUntilSuccess(Supplier<Optional<T>> attempt, int maxAttempts) {
    long opoznienie = 20;
    for (int p=1;p<=maxAttempts;p++) {
        Optional<T> wynik = attempt.get();
        if (wynik.isPresent()) return wynik.get();
        try { Thread.sleep(opoznienie); } catch (Exception e) {}
        opoznienie *= 2;
    }
    throw new RuntimeException("wyczerpano proby");
}
