static String classifyThreadIssue(Thread t, long observeMs) throws InterruptedException {
    Set<Thread.State> obserwowane = new HashSet<>();
    long koniec = System.currentTimeMillis()+observeMs;
    while (System.currentTimeMillis() < koniec) { obserwowane.add(t.getState()); Thread.sleep(50); }
    if (obserwowane.equals(Set.of(Thread.State.RUNNABLE))) return "LIVELOCK_SUSPECT";
    if (obserwowane.stream().allMatch(s -> s == Thread.State.BLOCKED || s == Thread.State.WAITING)) return "DEADLOCK_SUSPECT";
    return "NORMAL";
}
