static int countAttemptsToResolve(Runnable collisionScenario, AtomicInteger attemptCounter, long maxWaitMs) throws InterruptedException {
    Thread t = new Thread(collisionScenario);
    t.setDaemon(true);
    t.start();
    t.join(maxWaitMs);
    return t.isAlive() ? -1 : attemptCounter.get();
}
